import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Rhinocs_%E3%82%BB%E3%83%83%E3%83%88%E3%82%A2%E3%83%83%E3%83%97.html","title":"Rhinocs_セットアップ","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.07,"words":320},"filePathRelative":"Rhinocs_セットアップ.md"}`),a={name:`Rhinocs_セットアップ.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="rhinocs-セットアップ" tabindex="-1"><a class="header-anchor" href="#rhinocs-セットアップ"><span>Rhinocs_セットアップ</span></a></h1><p><a href="./Rhinocs.html">Rhinocs</a>のインストールとセットアップ手順。</p><h2 id="解説動画" tabindex="-1"><a class="header-anchor" href="#解説動画"><span>解説動画</span></a></h2><p><a href="https://www.youtube.com/watch?v=vTVCbSpzEfI" target="_blank" rel="noopener noreferrer">Rhinocsのインストールとセットアップ方法 - YouTube</a></p><h2 id="関連レポジトリ" tabindex="-1"><a class="header-anchor" href="#関連レポジトリ"><span>関連レポジトリ</span></a></h2><ul><li><a href="https://github.com/karino2/Rhinocs" target="_blank" rel="noopener noreferrer">karino2/Rhinocs: Rhino backed Android editor only for keyboard.</a> apkがある</li><li><a href="https://github.com/karino2/RhinocsJSPackage" target="_blank" rel="noopener noreferrer">karino2/RhinocsJSPackage: JS package repository for Rhinocs.</a> Rhinocsで使用するパッケージ。この中身のルートを指定しておく。</li></ul><h2 id="セットアップの概要" tabindex="-1"><a class="header-anchor" href="#セットアップの概要"><span>セットアップの概要</span></a></h2><p>セットアップは以下の手順になる。</p><ol><li>apkをインストール</li><li>JSPackageを端末に置く</li><li>M-x setupでデバイスIDと2のディレクトリを指定</li></ol><h3 id="apkとインストール" tabindex="-1"><a class="header-anchor" href="#apkとインストール"><span>apkとインストール</span></a></h3><p>RhinocsレポジトリのReleasesページ、<a href="https://github.com/karino2/Rhinocs/releases" target="_blank" rel="noopener noreferrer">Releases · karino2/Rhinocs</a>にあるapp-release.apkを端末にダウンロードして実行する。</p><p>これでRhinocsがインストール出来る。</p><h3 id="jsパッケージの配置" tabindex="-1"><a class="header-anchor" href="#jsパッケージの配置"><span>JSパッケージの配置</span></a></h3><p>RhinocsはJavaScriptで書かれたパッケージをロードして動くので、これを置く。</p><p><a href="https://github.com/karino2/RhinocsJSPackage/releases" target="_blank" rel="noopener noreferrer">Releases · karino2/RhinocsJSPackage</a> から最新のバージョンの「RhinocsJS.zip」をダウンロードして展開し、端末のどこかに置く（名前は好きにつけて良いが、ここではRhinocsJSと呼ぶ事にする）。</p><p>なお、サブモジュールごとgit cloneして<a href="./Syncthing.html">Syncthing</a>で共有する方がアップデートはやりやすいかもしれない。</p><h3 id="セットアップ" tabindex="-1"><a class="header-anchor" href="#セットアップ"><span>セットアップ</span></a></h3><p><code>M-x setup</code> を実行して、デバイスIDと上記RhinocsJSのディレクトリを指定する。</p><p>デバイスIDはJSのパッケージが保存する時のディレクトリ名に使うだけなので、もし<a href="./Syncthing.html">Syncthing</a>などで共有する予定が無ければ何も指定しなくてもいいのだが（その場合はDefaultになる）、一応指定しておく事を勧める。 PixelとかMotoG53yとか適当な自分の持っている端末内でかぶらない何かのIDならなんでも良い。</p><p>デバイスIDについては後述の「パッケージのストレージ」も参照のこと。</p><h3 id="init-jsのカスタマイズ-したければ" tabindex="-1"><a class="header-anchor" href="#init-jsのカスタマイズ-したければ"><span>init.jsのカスタマイズ（したければ）</span></a></h3><p>RhinocsJS/init.js ファイルは、ユーザーが自分に合わせて修正する事を意図している。</p><p>現在はapkのassetsに含まれる <a href="https://github.com/karino2/Rhinocs/blob/main/app/src/main/assets/builtins.js" target="_blank" rel="noopener noreferrer">Rhinocs/app/src/main/assets/builtins.js at main · karino2/Rhinocs</a> を見ながら書く感じになっている。</p><h2 id="ファイラー関連" tabindex="-1"><a class="header-anchor" href="#ファイラー関連"><span>ファイラー関連</span></a></h2><p>emacsと大きく違う所として、ファイル入出力周りの扱いがSAFベースになっている事がある。 C-x C-fは動くけれど、あまり使わない。</p><p>通常は編集対象のファイルのあるディレクトリを指定して、その下のファイルを開く、という風にする。 そこで最初に編集対象のディレクトリをファイラーに登録する、というのが普通の手順になる。</p><ul><li><code>C-x C-d r</code> で編集対象のファイルのあるディレクトリを登録（複数可能）</li></ul><p>こうして登録したら、以下のように開く。</p><ul><li><code>C-x C-d f</code> で最後にファイラーが使ったディレクトリからファイル名で開く</li><li><code>C-x C-d d</code> で、まず登録されているディレクトリを選んで、そのあとその下のファイルを開く</li></ul><h2 id="ヒストリ" tabindex="-1"><a class="header-anchor" href="#ヒストリ"><span>ヒストリ</span></a></h2><p>Androidではプロセスが良く殺されるので、メモリ内のバッファの一覧はちょくちょく失われる。そこでヒストリをファイルに保存するようになっていて、 ここから開く方が多い。</p><p>ヒストリは <code>C-x h</code> にバインドしてある。</p><h2 id="パッケージのストレージ" tabindex="-1"><a class="header-anchor" href="#パッケージのストレージ"><span>パッケージのストレージ</span></a></h2><p>パッケージが使うデータは、<code>RhinocsJS/storage/per_device/(デバイスID)/</code> 下に保存される。 <code>(デバイスID)</code> の所はセットアップで指定したデバイスID。</p><p>ヒストリやファイラーなどで保存したものはここに保存されるので、何かリセットしたくなったらこの該当ファイルを削除すれば良い。</p><h2 id="このページのshorturl" tabindex="-1"><a class="header-anchor" href="#このページのshorturl"><span>このページのshorturl</span></a></h2><p>YouTubeの概要欄などに貼る用。 <code>https://tinyurl.com/334t7cfd</code></p>`,37)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};